1	import { dirname } from 'node:path';
2	
3	// Generic scanning helpers for checks. The caller owns which files matter and
4	// which tokens are forbidden or required — these helpers only do the walking,
5	// so a check that must assert a word's presence or absence over a file set
6	// stays a few lines long. Nothing here carries content knowledge of its own.
7	
8	// Every line in `files` where `re` matches: [{ file, line, text }], 1-indexed,
9	// ready to anchor findings. Pass a non-global regex.
10	export function matchingLines(ctx, files, re) {
11	  const out = [];
12	  for (const f of files) {
13	    const text = ctx.read(f);
14	    if (text === null) continue;
15	    text.split('\n').forEach((ln, i) => {
16	      if (re.test(ln)) out.push({ file: f, line: i + 1, text: ln });
17	    });
18	  }
19	  return out;
20	}
21	
22	// Every line the current change ADDED (vs the scoping base) across `files` —
23	// defaults to every in-scope file the change touched. The "changed lines of
24	// the current pull request": a check-the-work rule scans these to judge the
25	// work itself instead of re-auditing the world, so legacy state the change
26	// never touched stays quiet (the same scoping the squash-merge effect check
27	// uses).
28	export function addedLines(ctx, files = ctx.changedFiles) {
29	  return files.flatMap((f) => ctx.addedLines(f).map((l) => ({ file: f, ...l })));
30	}
31	
32	// Rule ids (`id: '...'`) declared by the rule modules directly in `dir` —
33	// introspection of the engine's own rule-module format, not content knowledge.
34	// Pack manifests are skipped (their id is the pack's name, not a rule's), as
35	// are test files (their fixtures declare throwaway ids).
36	export function ruleIdsIn(ctx, dir) {
37	  const ids = new Set();
38	  for (const f of ctx.files) {
39	    if (dirname(f) !== dir || !f.endsWith('.mjs')) continue;
40	    if (f.endsWith('/pack.mjs') || f.endsWith('.test.mjs')) continue;
